ground_truth_sql:
SELECT "nct", "author", "year", "publication_type", "lines_of_treatment", "therapy_modality", "cancer_type", "combination_type", "trial_phase"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Non-Small Cell Lung' AND NULLIF(regexp_replace(("lines_of_treatment")::text, '[^0-9\.-]', '', 'g'), '')::numeric >= 2 AND "therapy_modality" = 'Combination';

gt_sql_final:
SELECT "nct", "author", "year", "originial_publication_or_follow_up", "lines_of_treatment", "monotherapy_combination", "cancer_type", "type_of_combination", "trial_phase"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Non-Small Cell Lung' AND NULLIF(regexp_replace(("lines_of_treatment")::text, '[^0-9\.-]', '', 'g'), '')::numeric >= 2 AND "monotherapy_combination" = 'Combination';
